const items = $input.all();

const data = items
  .map(item => item.json)
  .sort((a, b) => Number(a.Semana) - Number(b.Semana));

const camposParaComparar = [
  "Receita (Mi)",
  "Share",
  "Pedidos",
  "Ticket",
  "ROI",
  "Sellout (Mi)",
  "Share Multi",
  "Lojas Ativas",
  "Ticket Médio Loja",
  "Ticket Médio Pedido",
  "Ticket Geral CRM",
  "Ticket Geral CA",
  "Ticket Assistida CRM",
  "Ticket Assistida CA",
  "Ticket Orgânica CRM",
  "Ticket Orgânica CA",
  "Ticket Unilever CRM",
  "Ticket Unilever CA",
  "Ticket Outras CRM",
  "Ticket Outras CA",
  "Pedidos CRM",
  "Pedidos CA",
  "Receita CRM (Mi)",
  "Receita CA (Mi)",
  "Lojas CRM",
  "Lojas CA"
];

const resultado = data.map((atual, index) => {

  const anterior = data[index - 1];

  const variacoes = {};
  const sinais = [];

  // Comparação com a semana anterior
  if (anterior) {

    for (const campo of camposParaComparar) {

      const valorAtual = Number(atual[campo]);
      const valorAnterior = Number(anterior[campo]);

      if (
        Number.isFinite(valorAtual) &&
        Number.isFinite(valorAnterior) &&
        valorAnterior !== 0
      ) {

        const variacao =
          ((valorAtual - valorAnterior) / valorAnterior) * 100;

        variacoes[campo] = {
          atual: valorAtual,
          anterior: valorAnterior,
          variacao_percentual: Number(variacao.toFixed(2))
        };

        // Ponto de atenção
        if (variacao <= -5) {
          sinais.push({
            tipo: "ponto_de_atencao",
            indicador: campo,
            valor_atual: valorAtual,
            valor_anterior: valorAnterior,
            variacao_percentual: Number(variacao.toFixed(2))
          });
        }

        // Oportunidade
        if (variacao >= 5) {
          sinais.push({
            tipo: "oportunidade",
            indicador: campo,
            valor_atual: valorAtual,
            valor_anterior: valorAnterior,
            variacao_percentual: Number(variacao.toFixed(2))
          });
        }
      }
    }
  }

  // Análise das metas
  const metas = [
    {
      indicador: "% Meta Geral",
      valor: Number(atual["% Meta Geral"])
    },
    {
      indicador: "% Meta Unilever",
      valor: Number(atual["% Meta Unilever"])
    },
    {
      indicador: "% Meta Multi",
      valor: Number(atual["% Meta Multi"])
    }
  ];

  for (const meta of metas) {

    if (!Number.isFinite(meta.valor)) continue;

    const percentual = meta.valor * 100;

    if (percentual >= 100) {
      sinais.push({
        tipo: "meta_superada",
        indicador: meta.indicador,
        percentual_meta: Number(percentual.toFixed(1))
      });
    }

    if (percentual < 80) {
      sinais.push({
        tipo: "meta_abaixo_do_esperado",
        indicador: meta.indicador,
        percentual_meta: Number(percentual.toFixed(1))
      });
    }
  }

  return {
    json: {
      mes: atual["Mês"],
      semana: atual["Semana"],

      dados: {
        ...atual,
        row_number: undefined
      },

      variacoes_semana: variacoes,

      sinais: sinais
    }
  };
});

return resultado;

const items = $input.all();

const resultado = [];

for (const item of items) {

  const dados = item.json;
  const sinais = dados.sinais || [];

  const sinaisPrioritarios = sinais.map(sinal => {

    let prioridade = "baixa";
    let pontuacao = 1;

    const variacao = Number(sinal.variacao_percentual);

    if (Number.isFinite(variacao)) {

      const magnitude = Math.abs(variacao);

      if (magnitude >= 10) {
        prioridade = "alta";
        pontuacao = 3;
      } 
      else if (magnitude >= 5) {
        prioridade = "media";
        pontuacao = 2;
      }
    }

    // Metas recebem prioridade maior
    if (
      sinal.tipo === "meta_superada" ||
      sinal.tipo === "meta_abaixo_do_esperado"
    ) {

      const percentualMeta = Number(sinal.percentual_meta);

      if (percentualMeta >= 120 || percentualMeta < 60) {
        prioridade = "alta";
        pontuacao = 3;
      } 
      else {
        prioridade = "media";
        pontuacao = 2;
      }
    }

    return {
      ...sinal,
      prioridade,
      pontuacao
    };
  });

  // Ordena do mais importante para o menos importante
  sinaisPrioritarios.sort(
    (a, b) => b.pontuacao - a.pontuacao
  );

  resultado.push({
    json: {
      mes: dados.mes,
      semana: dados.semana,

      dados: dados.dados,

      sinais_priorizados: sinaisPrioritarios,

      resumo_priorizacao: {
        alta: sinaisPrioritarios.filter(
          s => s.prioridade === "alta"
        ).length,

        media: sinaisPrioritarios.filter(
          s => s.prioridade === "media"
        ).length,

        baixa: sinaisPrioritarios.filter(
          s => s.prioridade === "baixa"
        ).length
      }
    }
  });
}

return resultado;

