let contexto = [];

for (const item of entrada) {
  const json = item.json;

  // Caso o node anterior já entregue contexto_analise
  if (json.contexto_analise) {
    if (Array.isArray(json.contexto_analise)) {
      contexto.push(...json.contexto_analise);
    } else {
      contexto.push(json.contexto_analise);
    }
  }
}

// Se não encontrou contexto_analise, tenta utilizar os próprios dados
if (contexto.length === 0) {
  contexto = entrada.map(item => item.json);
}

// Remove possíveis duplicados
const contextoUnico = contexto.filter((item, index, array) => {
  const semana = item.semana ?? item.dados?.Semana;
  const mes = item.mes ?? item.dados?.Mês;

  return (
    array.findIndex(outro => {
      const outraSemana = outro.semana ?? outro.dados?.Semana;
      const outroMes = outro.mes ?? outro.dados?.Mês;

      return semana === outraSemana && mes === outroMes;
    }) === index
  );
});

