const raw = $json.relatorio_semanal || '';

// 1. Normaliza quebras de linha e aspas escapadas vindas da LLM
const text = raw
  .replace(/\\n/g, '\n')
  .replace(/\\"/g, '"');

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// 2. Divide o texto em seções, usando os cabeçalhos que a LLM sempre gera
const headerRegex = /(🎯\s*METAS|🟢\s*PONTOS POSITIVOS|🟡\s*ESTÁVEIS\s*\/\s*DENTRO DO ESPERADO|🔴\s*PONTOS DE ATENÇÃO|⚖️\s*CA x CRM|💡\s*OPORTUNIDADES|📌\s*RESUMO EXECUTIVO)/g;

const rawParts = text.split(headerRegex);
const sections = {};
// rawParts[0] = título antes do primeiro cabeçalho (ignorado)
for (let i = 1; i < rawParts.length; i += 2) {
  const header = rawParts[i].replace(/\s+/g, ' ').trim();
  const content = (rawParts[i + 1] || '').trim();
  sections[header] = content;
}

function getSection(keyPart) {
  const key = Object.keys(sections).find(k => k.includes(keyPart));
  return key ? sections[key] : '';
}

const metasSection = getSection('METAS');
const positivosSection = getSection('POSITIVOS');
const estaveisSection = getSection('ESTÁVEIS');
const atencaoSection = getSection('ATENÇÃO');
const caCrmSection = getSection('CA x CRM');
const oportunidadesSection = getSection('OPORTUNIDADES');
const resumoSection = getSection('RESUMO EXECUTIVO');

// 3. Extrai os blocos de metas (funciona com qualquer nome/quantidade de metas)
function parseMetas(str) {
  const regex = /[🟢🟡🔴]\s*Meta\s+([^\n]+)\n-\s*Realizado:\s*([^\n]+)\n-\s*Meta:\s*([^\n]+)\n-\s*Atingimento:\s*([^\n]+)\n-\s*Situação:\s*([^\n]+)/g;
  const metas = [];
  let m;
  while ((m = regex.exec(str)) !== null) {
    metas.push({
      nome: m[1].trim(),
      realizado: m[2].trim(),
      meta: m[3].trim(),
      atingimento: m[4].trim(),
      situacao: m[5].trim()
    });
  }
  return metas;
}

// 4. Extrai bullets simples (linhas que começam com •)
function parseBullets(str) {
  const regex = /•\s*([^\n]+)/g;
  const bullets = [];
  let m;
  while ((m = regex.exec(str)) !== null) {
    bullets.push(m[1].trim());
  }
  return bullets;
}

// 5. Extrai os blocos CA x CRM
function parseCaCrm(str) {
  const regex = /•\s*([^\n]+)\n\s*-\s*CRM:\s*([^\n]+)\n\s*-\s*CA:\s*([^\n]+)\n\s*-\s*Diferença:\s*([^\n]+)\n\s*-\s*Maior valor:\s*([^\n]+)/g;
  const rows = [];
  let m;
  while ((m = regex.exec(str)) !== null) {
    rows.push({
      indicador: m[1].trim(),
      crm: m[2].trim(),
      ca: m[3].trim(),
      diferenca: m[4].trim(),
      maior: m[5].trim()
    });
  }
  return rows;
}

const metas = parseMetas(metasSection);
const positivos = parseBullets(positivosSection);
const estaveis = parseBullets(estaveisSection);
const atencao = parseBullets(atencaoSection);
const oportunidades = parseBullets(oportunidadesSection);
const caCrm = parseCaCrm(caCrmSection);
const resumo = resumoSection.replace(/\n+/g, ' ').trim();

// 6. Helpers de estilo condicional
function corSituacao(situacao) {
  const s = situacao.toLowerCase();
  if (s.includes('superada') || s.includes('atingida')) return { bg: '#eafaf0', border: '#22a35a', text: '#1c7a44' };
  if (s.includes('não') || s.includes('abaixo')) return { bg: '#fdf1f0', border: '#d9463e', text: '#b3352d' };
  return { bg: '#fdf8ec', border: '#e0a613', text: '#9a7409' };
}

function corMaiorValor(maior) {
  const m = maior.toLowerCase();
  if (m.includes('crm')) return '#1c7a44';
  if (m.includes('ca')) return '#b3352d';
  return '#6b7280';
}

